PREFIX ns: <http://rdf.freebase.com/ns/>
SELECT DISTINCT ?event WHERE {
  {
    # When did the New York Giants win the Super Bowl prior to Feb. 3, 2008?
    ns:m.0713r ns:sports.sports_team.championships ?event .
    ?event ns:sports.sports_championship_event.championship ns:m.06x5s .
    ?event ns:time.event.end_date ?endDate .
    FILTER (?endDate < "2008-02-03"^^xsd:dateTime)
  }
  UNION
  {
    # In what event ending after 5 February 2006 did the Seattle Seahawks go to the Super Bowl?
    ns:m.070xg ns:sports.sports_team.championships ?event .
    ?event ns:sports.sports_championship_event.championship ns:m.06x5s .
    ?event ns:time.event.end_date ?endDate .
    FILTER (?endDate > "2006-02-05"^^xsd:dateTime)
  }
  UNION
  {
    # What was the earliest-ending event in the year that the Seattle Seahawks went to the Super Bowl?
    ns:m.06x5s ns:sports.sports_championship.events ?event .
    {
      ?event ns:sports.sports_championship_event.champion ns:m.070xg .
      UNION
      ?event ns:sports.sports_championship_event.runner_up ns:m.070xg .
    }
    ?event ns:time.event.end_date ?endDate .
  }
}
ORDER BY ?endDate
LIMIT 1

